struct PSplitBN16SSFuture38PackedEight {
  uint4 bits;
  CUTE_DEVICE uint16_t raw(int lane) const {
    const uint32_t word = lane < 2 ? bits.x : lane < 4 ? bits.y
                                            : lane < 6 ? bits.z : bits.w;
    return uint16_t(word >> (16 * (lane & 1)));
  }
};

template <class Element>
CUTE_DEVICE PSplitBN16SSFuture38PackedEight psplit_tma_inplace_ss_read_eight(const Element* ptr) {
  PSplitBN16SSFuture38PackedEight result;
  asm volatile("ld.global.v4.u32 {%0, %1, %2, %3}, [%4];"
      : "=r"(result.bits.x),"=r"(result.bits.y),
        "=r"(result.bits.z),"=r"(result.bits.w)
      : "l"(ptr) : "memory");
  return result;
}

template <class Element>
CUTE_DEVICE float psplit_tma_inplace_ss_unpack(const PSplitBN16SSFuture38PackedEight& packed,int lane) {
  return float(Element::bitcast(packed.raw(lane)));
}

CUTE_DEVICE void psplit_tma_inplace_ss_store_eight(void* ptr,const PSplitBN16SSFuture38PackedEight& v) {
  const uint32_t address = uint32_t(__cvta_generic_to_shared(ptr));
  asm volatile("st.shared.v4.b32 [%0], {%1, %2, %3, %4};"
      :: "r"(address),"r"(v.bits.x),"r"(v.bits.y),
         "r"(v.bits.z),"r"(v.bits.w) : "memory");
}

template <class Element>
CUTE_DEVICE uint32_t psplit_tma_inplace_ss_round_pair(float even,float odd) {
  cutlass::Array<float,2> source;
  source[0] = even; source[1] = odd;
  using Converter = cutlass::NumericArrayConverter<
      Element,float,2,cutlass::FloatRoundStyle::round_to_nearest>;
  const auto rounded = Converter{}(source);
  static_assert(sizeof(rounded) == sizeof(uint32_t),"one pair is one packed word");
  // Same representation cast as the existing cooperative paired converter.
  return reinterpret_cast<const uint32_t&>(rounded);
}

CUTE_DEVICE void psplit_tma_inplace_ss_put_word(PSplitBN16SSFuture38PackedEight& out,int pair,uint32_t word) {
  if (pair == 0) out.bits.x = word;
  else if (pair == 1) out.bits.y = word;
  else if (pair == 2) out.bits.z = word;
  else out.bits.w = word;
}

// Each task owns eight K elements of one row. All256 tasks are assigned once
// to128 producer threads. Every original quadrant vector is read exactly once
// for this CTA/stage and every final seven-slot A element has one writer.
template <class Element,class SmemA>
CUTE_DEVICE void psplit_tma_inplace_ss_fill_a(const Problem& p,const Element* A,
    int64_t row_base,int64_t k_base,int task,SmemA sA) {
  const int64_t mh = p.m/2, kh = p.k/2;
  const int row = task/4, k = (task&3)*8;
  const int64_t gr = row_base+row, gk = k_base+k;
  const auto a11 = psplit_tma_inplace_ss_read_eight(A + gr*p.lda + gk);
  const auto a12 = psplit_tma_inplace_ss_read_eight(A + gr*p.lda + gk + kh);
  const auto a21 = psplit_tma_inplace_ss_read_eight(A + (gr+mh)*p.lda + gk);
  const auto a22 = psplit_tma_inplace_ss_read_eight(A + (gr+mh)*p.lda + gk + kh);
  psplit_tma_inplace_ss_store_eight(&sA(row,k,0),a11);
  psplit_tma_inplace_ss_store_eight(&sA(row,k,1),a12);
  psplit_tma_inplace_ss_store_eight(&sA(row,k,3),a22);
  PSplitBN16SSFuture38PackedEight s1{make_uint4(0,0,0,0)},s2{make_uint4(0,0,0,0)};
  PSplitBN16SSFuture38PackedEight s3{make_uint4(0,0,0,0)},s4{make_uint4(0,0,0,0)};
  CUTE_UNROLL
  for (int pair = 0; pair < 4; ++pair) {
    float f1[2],f2[2],f3[2],f4[2];
    CUTE_UNROLL
    for (int j = 0; j < 2; ++j) {
      const int lane = 2*pair+j;
      const float x11 = psplit_tma_inplace_ss_unpack<Element>(a11,lane);
      const float x12 = psplit_tma_inplace_ss_unpack<Element>(a12,lane);
      const float x21 = psplit_tma_inplace_ss_unpack<Element>(a21,lane);
      const float x22 = psplit_tma_inplace_ss_unpack<Element>(a22,lane);
      f1[j] = __fadd_rn(x21,x22);
      f2[j] = __fsub_rn(f1[j],x11);
      f3[j] = __fsub_rn(x11,x21);
      f4[j] = __fsub_rn(x12,f2[j]);
    }
    psplit_tma_inplace_ss_put_word(s1,pair,psplit_tma_inplace_ss_round_pair<Element>(f1[0],f1[1]));
    psplit_tma_inplace_ss_put_word(s2,pair,psplit_tma_inplace_ss_round_pair<Element>(f2[0],f2[1]));
    psplit_tma_inplace_ss_put_word(s3,pair,psplit_tma_inplace_ss_round_pair<Element>(f3[0],f3[1]));
    psplit_tma_inplace_ss_put_word(s4,pair,psplit_tma_inplace_ss_round_pair<Element>(f4[0],f4[1]));
  }
  psplit_tma_inplace_ss_store_eight(&sA(row,k,2),s4);
  psplit_tma_inplace_ss_store_eight(&sA(row,k,4),s1);
  psplit_tma_inplace_ss_store_eight(&sA(row,k,5),s2);
  psplit_tma_inplace_ss_store_eight(&sA(row,k,6),s3);
}

