  const auto b11 = psplit_tma_inplace_ss_read_eight(B + gk*p.ldb + gc);
  const auto b12 = psplit_tma_inplace_ss_read_eight(B + gk*p.ldb + gc + nh);
  const auto b21 = psplit_tma_inplace_ss_read_eight(B + (gk+kh)*p.ldb + gc);
  const auto b22 = psplit_tma_inplace_ss_read_eight(B + (gk+kh)*p.ldb + gc + nh);
  psplit_tma_inplace_ss_store_eight(&sB(col,k,0),b11);
  psplit_tma_inplace_ss_store_eight(&sB(col,k,1),b21);
  psplit_tma_inplace_ss_store_eight(&sB(col,k,2),b22);
  PSplitBN16SSFuture38PackedEight t1{make_uint4(0,0,0,0)},t2{make_uint4(0,0,0,0)};
  PSplitBN16SSFuture38PackedEight t3{make_uint4(0,0,0,0)},t4{make_uint4(0,0,0,0)};
  CUTE_UNROLL
  for (int pair = 0; pair < 4; ++pair) {
    float f1[2],f2[2],f3[2],f4[2];
    CUTE_UNROLL
    for (int j = 0; j < 2; ++j) {
      const int lane = 2*pair+j;
      const float x11 = psplit_tma_inplace_ss_unpack<Element>(b11,lane);
      const float x12 = psplit_tma_inplace_ss_unpack<Element>(b12,lane);
      const float x21 = psplit_tma_inplace_ss_unpack<Element>(b21,lane);
      const float x22 = psplit_tma_inplace_ss_unpack<Element>(b22,lane);
      f1[j] = __fsub_rn(x12,x11);
      f2[j] = __fsub_rn(x22,f1[j]);
      f3[j] = __fsub_rn(x22,x12);
      f4[j] = __fsub_rn(f2[j],x21);
    }
    psplit_tma_inplace_ss_put_word(t1,pair,psplit_tma_inplace_ss_round_pair<Element>(f1[0],f1[1]));
    psplit_tma_inplace_ss_put_word(t2,pair,psplit_tma_inplace_ss_round_pair<Element>(f2[0],f2[1]));
    psplit_tma_inplace_ss_put_word(t3,pair,psplit_tma_inplace_ss_round_pair<Element>(f3[0],f3[1]));
    psplit_tma_inplace_ss_put_word(t4,pair,psplit_tma_inplace_ss_round_pair<Element>(f4[0],f4[1]));
  }
  psplit_tma_inplace_ss_store_eight(&sB(col,k,3),t4);
  psplit_tma_inplace_ss_store_eight(&sB(col,k,4),t1);
  psplit_tma_inplace_ss_store_eight(&sB(col,k,5),t2);
  psplit_tma_inplace_ss_store_eight(&sB(col,k,6),t3);
}

